#[derive(Deserialize)]
#[serde(tag = "attribution_status", rename_all = "snake_case")]
enum AttributionRow {
    Selected {
        funding_entry_id: String,
        selected_funder_id: String,
        attribution_basis: String,
        selected_parent_declaration_id: Option<u32>,
        issues: Vec<String>,
    },
    Unavailable {
        funding_entry_id: String,
        unavailable_reason: String,
        issues: Vec<String>,
    },
}
impl AttributionRow {
    fn funding_entry_id(&self) -> &str {
        match self {
            Self::Selected {
                funding_entry_id, ..
            }
            | Self::Unavailable {
                funding_entry_id, ..
            } => funding_entry_id,
        }
    }

    fn is_valid(&self) -> bool {
        let valid_issues = |issues: &[String]| {
            issues
                .iter()
                .all(|issue| issue == "explicit_ultimate_payer_with_parent_payer_same_flag")
        };
        match self {
            Self::Selected {
                attribution_basis,
                issues,
                ..
            } => {
                matches!(
                    attribution_basis.as_str(),
                    "explicit_ultimate_payer" | "parent_payer" | "donor" | "payer"
                ) && valid_issues(issues)
            }
            Self::Unavailable {
                unavailable_reason,
                issues,
                ..
            } => {
                matches!(
                    unavailable_reason.as_str(),
                    "explicit_ultimate_payer_unavailable"
                        | "different_ultimate_payer_unnamed"
                        | "parent_cycle"
                        | "parent_payer_unavailable"
                        | "parent_evidence_unavailable"
                        | "parent_payer_ambiguous"
                        | "donor_unavailable"
                        | "payer_unavailable"
                        | "no_supported_attribution"
                ) && valid_issues(issues)
            }
        }
    }
}

fn fingerprint_files(
    paths: impl IntoIterator<Item = PathBuf>,
) -> Result<String, EntityIngestionError> {
    let mut paths = paths.into_iter().collect::<Vec<_>>();
    paths.sort();
    let mut digest = Sha256::new();
    for path in paths {
        let name = path
            .file_name()
            .and_then(|name| name.to_str())
            .ok_or_else(|| data_error("artifact filename is not UTF-8"))?;
        let bytes = fs::read(&path).map_err(read_error)?;
        digest.update(u64::try_from(name.len()).unwrap_or(u64::MAX).to_be_bytes());
        digest.update(name.as_bytes());
        digest.update(u64::try_from(bytes.len()).unwrap_or(u64::MAX).to_be_bytes());
        digest.update(bytes);
    }
    Ok(format!("{:x}", digest.finalize()))
}

